package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

var scanner = bufio.NewScanner(os.Stdin)

func readLn() string {
	scanner.Scan()
	return scanner.Text()
}

func readInt() int {
	n, _ := strconv.Atoi(readLn())
	return n
}

func readStrings() []string {
	return strings.Split(readLn(), " ")
}

func readInts() []int {
	values := readStrings()
	result := make([]int, len(values))
	for i, value := range values {
		result[i], _ = strconv.Atoi(value)
	}
	return result
}

func findLissPos() int {
	stones := readLn()
	instructions := readLn()
	curPos := 0

	for i := 0; i < len(instructions); i++ {
		if stones[curPos] == instructions[i] {
			curPos++
		}
	}

	curPos++
	return curPos
}

func main() {
	fmt.Print(findLissPos())
}

